def round_half_to_even(n):
    """Round a number to the nearest integer, rounding half to even.

    This function rounds a floating-point number to the nearest integer.
    If the number is exactly halfway between two integers, it rounds to the
    nearest even integer. This method is often used to avoid rounding bias in
    calculations.

    :param n: The floating-point number to round.
    :return: The rounded integer.
    """
    if n >= 0:
        return int(n + 0.5 - (n + 0.5) % 1)
    else:
        return int(n - 0.5 + (n - 0.5) % 1)

