def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, following the "round half to even" rule (also known as "bankers' rounding").

    Args:
        n (float): The number to round.

    Returns:
        int: The rounded integer.
    """
    if n > 0:
        return int(n + 0.5 - 0.5 * (abs(n + 0.5) % 2))
    else:
        return int(n - 0.5 + 0.5 * (abs(n - 0.5) % 2))

