def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Step 1: Validate input types
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, dict):
        raise TypeError("fields must be a dictionary")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Step 2: Validate fields dictionary
    for key, value in fields.items():
        if not isinstance(key, str) or not isinstance(value, tuple):
            raise ValueError("fields dictionary keys must be strings and values must be tuples")

    # Step 3: Validate SRID map
    for key, value in srid_map.items():
        if not isinstance(key, int) or not isinstance(value, str):
            raise ValueError("srid_map keys must be integers and values must be strings")

    # Step 4: Create the new Point subclass
    class_name = name.capitalize()
    Point subclass = type(class_name, (), {})

    # Step 5: Add fields to the subclass
    for key, value in fields.items():
        field_name, field_type = value
        if not isinstance(field_name, str) or not isinstance(field_type, type):
            raise ValueError("field names and types must be strings and type objects")
        setattr(subclass, key, field_type)

    # Step 6: Add SRID mapping to the subclass
    subclass.srid_map = srid_map

    return subclass
