import os
import sys

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Check if the command is empty or only contains comments
    if not cmd or all(c for c in cmd if c.startswith('#')):
        return cmd

    # Check if the first element is a shebang
    if cmd[0].startswith('#!'):
        # Normalize the shebang to an absolute path if it's a relative path
        if os.path.isabs(cmd[0]):
            normalized_cmd = (cmd[0],) + cmd[1:]
        else:
            # Convert to absolute path
            normalized_cmd = (os.path.abspath(cmd[0]),) + cmd[1:]
        return normalized_cmd
    else:
        return cmd

# Adding the check for Windows environment and the special case for python.exe
if os.name == 'nt':
    if len(cmd) > 0 and cmd[0] == 'python' and len(cmd[1:]) > 0:
        if cmd[1] == '-m':
            module = cmd[2]
            normalized_cmd = (os.path.join(sys.exec_prefix, 'Scripts', f'{module}.py'),) + cmd[3:]
            return normalized_cmd
        else:
            script = cmd[1]
            if os.path.isabs(script):
                normalized_cmd = (script,) + cmd[2:]
            else:
                normalized_cmd = (os.path.join(sys.exec_prefix, 'Scripts', script),) + cmd[2:]
                return normalized_cmd
    elif len(cmd) > 0 and cmd[0] == 'python':
        normalized_cmd = (os.path.join(sys.exec_prefix, 'python.exe'),) + cmd[1:]
        return normalized_cmd

    # Return the original command if it's already well-formed or not applicable
    return cmd
else:
    return cmd
