import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def wrapper_cache(user_function):
        @wraps(user_function)
        @lru_cache(maxsize=maxsize, typed=typed)
        def wrapper(self, *args, **kwargs):
            key = (args, tuple(kwargs.items()))
            result, expire = self.cache.get(key, (None, None))
            if result is not None and expire is not None and expire >= timer():
                return result
            result = user_function(self, *args, **kwargs)
            self.cache[key] = (result, timer() + ttl)
            return result
        wrapper.cache = {}
        return wrapper
    return wrapper_cache

