    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TtlCacheMiss(Exception):
        pass

    class TtlCacheWrapper:
        def __init__(self, func):
            self.func = func
            self.cache = {}
            self.lock = Lock()

        def __call__(self, *args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else (args, frozenset(kwargs.items()))
            with self.lock:
                try:
                    cache_entry = self.cache[key]
                except KeyError:
                    raise TtlCacheMiss
                if timer() - cache_entry['time'] > ttl:
                    del self.cache[key]
                    raise TtlCacheMiss
                return cache_entry['value']

        def __missing__(self, key):
            value = self.func(*key[0], **dict(key[1]))
            with self.lock:
                self.cache[key] = {'time': timer(), 'value': value}
                if len(self.cache) > maxsize:
                    oldest_key = min(self.cache.keys(), key=lambda k: self.cache[k]['time'])
                    del self.cache[oldest_key]
            return value

    return TtlCacheWrapper

