from functools import wraps, lru_cache

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrapper(func):
        @wraps(func)
        @lru_cache(maxsize=maxsize, typed=typed)
        def wrapped_func(*args, **kwargs):
            result = func(*args, **kwargs)
            wrapped_func.cache_info().add_expiration(result, timer(), ttl)
            return result

        def __repr__(self):
            return f"{self.func.__name__}({self.func.__qualname__})"

        wrapped_func.cache_info = Caching(wrapped_func.cache_info())
        return wrapped_func

    return wrapper


class Caching:
    def __init__(self, cache_info):
        self.cache_info = cache_info
        self.expire_times = {}

    def add_expiration(self, result, now, ttl):
        self.expire_times[id(result)] = now + ttl

    def __call__(self):
        return self.cache_info

    def keys(self):
        current_time = time.monotonic()
        valid_keys = [k for k, exp in self.expire_times.items() if exp > current_time]
        for k in set(self.expire_times.keys()) - set(valid_keys):
            del self.expire_times[k]
        return valid_keys
