def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize is None or maxsize <= 0:
        return None  # No caching

    cache = {}
    sentinel = object()

    def wrapper(func):
        def _cache_get(key):
            try:
                result = cache[key]
                if result is sentinel:
                    return None, True
                return result, False
            except KeyError:
                return None, False

        def _cache_set(key, result):
            cache[key] = result

        def _cache_delete(key):
            del cache[key]

        def _cache_clear():
            cache.clear()

        def _wrapper(*args, **kwargs):
            if typed:
                key = (func, args, tuple(kwargs.items()))
            else:
                key = (func, tuple(args), tuple(kwargs.items()))

            result, is_hit = _cache_get(key)
            if is_hit:
                return result

            result = func(*args, **kwargs)
            _cache_set(key, result)
            return result

        def _wrapper.cache_info():
            return _cache_info

        def _cache_info():
            return _CacheInfo(len(cache), _cache_clear)

        return _wrapper

    return wrapper

class _CacheInfo:
    def __init__(self, hits, clear):
        self.hits = hits
        self.clear = clear

    def __repr__(self):
        return f"CacheInfo(hits={self.hits}, clear={self.clear.__func__.__name__})"

