def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps
    from collections import OrderedDict

    if maxsize <= 0:
        raise ValueError('maxsize must be greater than 0')

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq

        def __repr__(self):
            return f"Node(key={self.key}, value={self.value}, freq={self.freq})"

    class LFUCache:
        def __init__(self, maxsize):
            self.cache = {}
            self.freqdist = OrderedDict()
            self.maxsize = maxsize
            self.size = 0

        def access(self, key):
            if key not in self.cache:
                raise KeyError(f"{key} not in cache")
            node = self.cache[key]
            del self.freqdist[node.freq]
            if not self.freqdist:
                del self.cache[key]
                self.size -= 1
            node.freq += 1
            if node.freq not in self.freqdist:
                self.freqdist[node.freq] = OrderedDict()
            self.freqdist[node.freq][key] = node
            return self.cache[key].value

        def add(self, key, value):
            if key in self.cache:
                self.cache[key].value = value
                self.access(key)
            else:
                if self.size >= self.maxsize:
                    lfu_key = next(iter(self.freqdist[min(self.freqdist)]))
                    del self.cache[lfu_key]
                    del self.freqdist[min(self.freqdist)][lfu_key]
                    self.size -= 1
                new_node = Node(key, value)
                self.cache[key] = new_node
                if 1 not in self.freqdist:
                    self.freqdist[1] = OrderedDict()
                self.freqdist[1][key] = new_node
                self.size += 1

    def decorator(func):
        nonlocal maxsize
        if not callable(func):
            raise TypeError(f"Expected callable, got {type(func).__name__}")
        cache = LFUCache(maxsize)
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args + tuple(sorted(kwargs.items()))
            try:
                return cache.access(key)
            except KeyError:
                result = func(*args, **kwargs)
                cache.add(key, result)
                return result

        return wrapper

    return decorator

