@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if isinstance(e, Exception):
        exception_string = str(e)
        try:
            if max_level > 0:
                stacktrace = traceback.format_exception(None, e, e.__traceback__)
                stacktrace = '\n'.join(stacktrace)
                stacktrace = cls.trim_stacktrace(stacktrace, max_level, max_path_level)
                exception_string += '\n' + stacktrace
        except Exception as ex:
            exception_string += '\nFailed to format stack trace: ' + str(ex)
        return exception_string
    else:
        raise ValueError("Input 'e' must be an instance of Exception.")

@classmethod
def trim_stacktrace(cls, stacktrace, max_level, max_path_level):
    lines = stacktrace.split('\n')
    trimmed_lines = []
    level = 0
    path_level = 0
    for line in lines:
        if 'File' in line:
            path_level += 1
        if not path_level > max_path_level:
            trimmed_lines.append(line)
            level += 1
            if level > max_level:
                break
    return '\n'.join(trimmed_lines)
