        if current_level > max_level:
            return "Max call stack level reached"

        exception_info = traceback.extract_tb(e.__traceback__)
        formatted_traceback = []

        for frame in exception_info:
            if len(current_path) < max_path_level:
                formatted_traceback.append(f"{frame.filename}:{frame.lineno} in {frame.name}")
                current_path.append(frame.filename)
            else:
                formatted_traceback.append("... (max path level reached)")
                break

        returnf"{e!r}:\n{''.join(formatted_traceback)}"
