                self.graph[u] = []
            self.graph[u].append(v)

        def topological_sort_util(self, v, visited, stack):
            visited.add(v)
            if v in self.graph:
                for neighbor in self.graph[v]:
                    if neighbor not in visited:
                        self.topological_sort_util(neighbor, visited, stack)
            stack.append(v)

