            for v in self.graph:
                if v not in visited:
                    self.topological_sort_util(v, visited, stack)

            return stack[::-1]

    def remove_redundant_classes(classes):
        graph = DependencyGraph()

        # Create a directed graph where each class points to its subclasses
        for cls in classes:
            for subclass in cls.__subclasses__():
                graph.add_edge(cls, subclass)

        # Topological sort the graph
        topologically_sorted_classes = graph.topological_sort()

        # Remove classes that are redundant (subclasses of other classes)
        minimal_classes = []
        for cls in topologically_sorted_classes:
            if not any(issubclass(cls, other) for other in minimal_classes):
                minimal_classes.append(cls)

        return minimal_classes

    return remove_redundant_classes(classes)
