def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_ancestor(a, b):
        return issubclass(b, a) and a is not b

    while True:
        changed = False
        for i in range(len(classes)):
            for j in range(len(classes)):
                if i != j and is_ancestor(classes[i], classes[j]):
                    classes.remove(classes[i])
                    changed = True
        if not changed:
            break

    return classes
