def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Helper function to determine if class a is a subclass of class b
    def is_subclass(a, b):
        return issubclass(a, b)

    # Remove duplicates and sort classes by their inheritance depth
    unique_classes = list(dict.fromkeys(classes))
    unique_classes.sort(key=lambda x: (len(x.__mro__), x))

    # Filter out classes that are subclasses of other classes in the list
    min_equivalent_classes = []
    for cls in unique_classes:
        if not any(is_subclass(cls, other) for other in unique_classes if other != cls):
            min_equivalent_classes.append(cls)

    return min_equivalent_classes

