            elif i not in context.error['y_low']:
                context.error['y_low'][i] = None

    for i, error_E_low in enumerate(self.error_E_low):
        if error_E_low > 0:
            if 'z_high' not in context.error:
                context.error['z_high'] = {'index': i}
            elif i not in context.error['z_high']:
                context.error['z_high'][i] = None

    for key, value in self.value.items():
        if key not in context.value:
            context.value[key] = value
        elif isinstance(value, dict):
            context.value[key].update(value)
