       add keyword argument *level*.
    """

    result = {}
    if level == 0:
        return result

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1  # or raise a ValueError if you expect only dictionaries

    if level == -1:
        level = float('inf')

    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            value_d1 = d1[key]
            value_d2 = d2[key]
            if isinstance(value_d1, dict) and isinstance(value_d2, dict):
                recursive_diff = difference(value_d1, value_d2, level - 1)
                if recursive_diff:
                    result[key] = recursive_diff
            elif value_d1 != value_d2:
                result[key] = value_d1

