def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0] or coord > self.edges[-1]:
        return

    index = bisect.bisect_left(self.edges, coord)
    if index > 0:
        self.data[index - 1] += weight * self.scale[index - 1]

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord >= self.edges[0] and coord <= self.edges[-1]:
        index = bisect.bisect_left(self.edges, coord)
        if index != len(self.edges) and self.edges[index] == coord:
            self.values[index] += weight
        else:
            self.values.insert(index, coord)
            self.values.insert(index, weight)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.min or coord > self.max:
        return
    bin_index = int((coord - self.min) / self.bin_width)
    if bin_index < 0 or bin_index >= len(self.bins):
        return
    self.bins[bin_index] += weight

