            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    label_key_regex = re.compile(r'^[a-zA-Z0-9_]*$')
    label_value_regex = re.compile(r'^[a-zA-Z0-9_]*$')

    errors = []

    for key, value in labels.items():
        if isinstance(value, list):
            for val in value:
                if not isinstance(val, (str, bytes)):
                    errors.append({"'{}'".format(val): 'expected string or bytes-like object'})
                elif not label_value_regex.match(val):
                    errors.append({repr(val): 'Label value "{}" does not match the regex'.format(val)})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({'{!r}'.format(value): 'expected string or bytes-like object'})
            elif not label_value_regex.match(value):
                errors.append({repr(value): 'Label value "{}" does not match the regex'.format(value)})

        if isinstance(key, bytes):
            errors.append({'{!r}'.format(key): 'expected string or bytes-like object'})
        elif not label_key_regex.match(key):
            errors.append({repr(key): 'Label key "{}" does not match the regex'.format(key)})

    if errors:
