def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, list):
        raise ValueError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise ValueError("observer_schema must be a list")
    if not isinstance(response, list):
        raise ValueError("response must be a list")

    for item in response:
        if isinstance(item, dict):
            found = any(
                item.get("fieldPath") ==观测字段Path
                for观测字段Path in observer_schema
            )
            if not found:
                last_applied_manifest.append(item)

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.

    """
    for observed_field, schema in zip(observer_schema, response):
        if isinstance(schema, dict):
            if observed_field not in last_applied_manifest:
                last_applied_manifest.append({observed_field: schema})
            else:
                update_last_applied_manifest_list_from_resp(last_applied_manifest[observed_field], schema, response)
        elif isinstance(schema, list):
            for item in schema:
                update_last_applied_manifest_list_from_resp(last_applied_manifest, observed_field, item)
        else:
            if observed_field not in last_applied_manifest:
                last_applied_manifest.append({observed_field: schema})

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    try:
        for field, nested_schema in observer_schema.items():
            if field in response:
                if isinstance(nested_schema, dict):
                    if field not in last_applied_manifest:
                        last_applied_manifest[field] = {}
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], nested_schema, response[field])
                elif nested_schema == "list":
                    if field not in last_applied_manifest:
                        last_applied_manifest[field] = []
                    update_last_applied_manifest_list_from_resp(last_applied_manifest[field], response[field])
                else:
                    if field not in last_applied_manifest or last_applied_manifest[field] is None:
                        last_applied_manifest[field] = response[field]
            else:
                raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
    except KeyError as e:
        raise KeyError(e)

