        sql_out = io.BytesIO()
    else:
        raise TypeError("sql must be a str or bytes object")

    if isinstance(params, dict):
        params_out = {}
    elif isinstance(params, (list, tuple)):
        params_out = []
    else:
        raise TypeError("params must be a Mapping or Sequence object")

    # Assuming SQLParams and in_style are defined elsewhere
    if SQLParams.in_style == 'named':
        for key, value in params.items():
            sql = sql.replace(f":{key}", "?")
            params_out[params_out.__class__({key: value})] = value
    elif SQLParams.in_style == 'ordinal':
        for i, value in enumerate(params):
            sql = sql.replace(f"?", "?", 1)
            params_out[params_out.__class__([value])] = value
    else:
        raise ValueError("Unsupported parameter style")

    return (sql_out.getvalue(), params_out)
