    """Helper method to validate each content file."""
    version_dir = os.path.join(path, content_id, version)
    inventory_path = os.path.join(version_dir, 'inventory.json')
    if not os.path.exists(inventory_path):
        raise ValueError(f"Inventory file does not exist for content ID {content_id} and version {version}")

    inventory = self.read_inventory(inventory_path)
    for logical_path, content_type in inventory.items():
        actual_path = os.path.join(version_dir, logical_path)
        if not os.path.exists(actual_path):
            raise FileNotFoundError(f"The file {logical_path} does not exist in the version directory")

        if content_type != self.get_content_type(actual_path):
