        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    referenced_files = set()

    for item in fixity.values():
        if not isinstance(item, dict):
            raise ValueError("Each fixity item must be a dictionary")
        if 'file' not in item:
            raise ValueError("Each fixity item must contain a 'file' key")
        file_path = item['file']
        if not isinstance(file_path, str):
            raise ValueError("File path must be a string")
        referenced_files.add(file_path)

    for file_path in manifest_files:
        if not isinstance(file_path, str):
            raise ValueError("Manifest files must be strings")

    if referenced_files != set(manifest_files):
        raise ValueError("Fixity block references files not listed in the manifest")

