    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] == 2:
        import codecs
        def wrapper():
            result = namefunc()
            if isinstance(result, unicode):
                result = codecs.encode(result, 'utf-8')
            return result
        return wrapper
    else:
