import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Validate input types
    if not isinstance(commands, (list, str)):
        raise TypeError("commands must be a list of strings or a single string")
    if not isinstance(args, list):
        raise TypeError("args must be a list")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary or None")

    # Construct the full command
    if isinstance(commands, str):
        commands = [commands]
    full_command = commands + args

    # Redirect stderr if required
    stderr = subprocess.STDOUT if hide_stderr else subprocess.PIPE

    # Run the command
    process = subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=stderr)
    stdout, stderr = process.communicate()

    # Print output if verbose
    if verbose:
        print(stdout.decode('utf-8'))

    # Check for errors
    if process.returncode != 0:
        raise subprocess.CalledProcessError(process.returncode, full_command, stdout, stderr)

    return stdout.decode('utf-8')
