        if sys.version_info[0] < 2:
            versionfile_abs = versionfile_abs.encode('ascii')
        f = open(versionfile_abs, 'rb')
        versiondata = f.read()
        f.close()
        if sys.version_info[0] < 2:
            versiondata = versiondata.decode('ascii')
    except IOError:
        return None

    if attrs is None:
        attrs = {}
    config = VersioneerConfig(versionfile_abs=versionfile_abs, versiondata=versiondata)

    try:
        config.version = config.version + config.prefix
    except AttributeError:
        pass

    if isinstance(versiondata, (str, unicode)):
        versiondata = versiondata.splitlines()

    try:
        versiondata = '\n'.join(config.versiondata)
        config.versiondata = versiondata.splitlines()
    except AttributeError:
        pass

    try:
        config.prefix = config.prefix or ''
    except AttributeError:
        pass

    try:
        config.version_annotation = config.version_annotation or version_annotation
    except AttributeError:
        pass

    try:
        config.versionfile_source = config.versionfile_source or versionfile_source
    except AttributeError:
        pass

    return config

