def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    # Helper function to validate an object
    def validate_object(obj):
        nonlocal good_objects
        try:
            if obj.validate(validate_objects, check_digests, show_warnings):
                good_objects += 1
                return True
            else:
                return False
        except Exception as e:
            if show_warnings:
                print(f"Warning: Error validating object {obj}: {e}")
            return False

    # Validate all objects in the hierarchy
    for obj in self.traverse():
        num_objects += 1
        if validate_object(obj):
            good_objects += 1

    return num_objects, good_objects

