def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    if not version_dirs:
        raise ValueError("version_dirs should not be empty")

    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.txt')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

        with open(inventory_path, 'r') as file:
            inventory = json.load(file)

        if root_inventory is None:
            root_inventory = inventory
        else:
            # Check for missing files in the current inventory
            for file, digest in root_inventory.items():
                if file not in inventory:
                    raise ValueError(f"File {file} is missing in version {version_dir} inventory")

        # Check for content digests different from the root inventory
        for file, digest in inventory.items():
            if file not in content_digests:
                content_digests[file] = digest
            elif content_digests[file] != digest:
                raise ValueError(f"Content digest mismatch for file {file} in version {version_dir}")

    # Check for any content digests in root inventory not present in the last version
    if version_dirs:
        last_version_dir = version_dirs[-1]
        last_inventory_path = os.path.join(last_version_dir, 'inventory.txt')
        with open(last_inventory_path, 'r') as file:
            last_inventory = json.load(file)

        for file, digest in root_inventory.items():
            if file not in last_inventory:
                raise ValueError(f"File {file} is present in root inventory but missing in version {last_version_dir} inventory")

