def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    from hashlib import sha256
    import os

    root_inventory_file = os.path.join(version_dirs[0], 'inventory.txt')
    if not os.path.exists(root_inventory_file):
        raise FileNotFoundError("Root inventory file not found")

    with open(root_inventory_file, 'r') as f:
        root_inventory = f.read().splitlines()

    content_digests = {}

    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.txt')
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"Inventory file for version {version_dir} not found")

        with open(inventory_file, 'r') as f:
            inventory = f.read().splitlines()

        for entry in inventory:
            if entry not in root_inventory:
                raise ValueError(f"Entry {entry} in version {version_dir} inventory is not in root inventory")

            file_path = entry.split()[1]
            with open(file_path, 'rb') as f:
                file_digest = sha256(f.read()).hexdigest()

            if file_path in content_digests:
                if content_digests[file_path] != file_digest:
                    raise ValueError(f"Content digest mismatch for file {file_path}: {content_digests[file_path]} vs {file_digest}")
            else:
                content_digests[file_path] = file_digest

    print("Validation passed")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory not found for version {version_dir}")

        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

            if root_inventory is None:
                root_inventory = inventory
                content_digests.update(inventory['content_digests'])
            else:
                if 'content_digests' in inventory:
                    for file, digest in inventory['content_digests'].items():
                        if file in content_digests and content_digests[file] != digest:
                            raise ContentDigestMismatchError(f"Content digest mismatch for file {file} in version {version_dir}")
                        content_digests[file] = digest
                else:
                    raise MissingContentDigestsError(f"Missing content digests for version {version_dir}")

        for file, path in inventory['files'].items():
            if not os.path.exists(path):
                raise FileNotFoundError(f"File {file} not found in version {version_dir}")

    # Check if all content digests from the root inventory are present
    for file, digest in root_inventory['content_digests'].items():
        if file not in content_digests or content_digests[file] != digest:
            raise MissingContentDigestError(f"Missing content digest for file {file} from root inventory")

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isdir(path):
            namaste_file_path = os.path.join(path, "0=*.txt")
            if os.path.isfile(namaste_file_path):
                with open(namaste_file_path, 'r') as file:
                    content = file.read()
                    if content.strip() == "OCFL Version 1.0":
                        return "root"
                    elif "object_info.json" in content:
                        return "object"
        elif os.path.isfile(path):
            return "file"
    except Exception as e:
        return str(e)

    return "unknown"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return "Path does not exist"

    if os.path.isfile(path):
        return "file"

    if os.path.isdir(path):
        namaste_file_path = os.path.join(path, "0=*")
        if os.path.exists(namaste_file_path):
            with open(namaste_file_path, 'r') as f:
                namaste_content = f.read().strip()
                if namaste_content == "root":
                    return "root"
                elif namaste_content == "object":
                    return "object"
                else:
                    return f"Unknown directory type: {namaste_content}"
        else:
            return "No Namaste file found"

    return "Unknown path type"

