    '''Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.'''

    import argparse
    import sys

    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Define your subparsers here
    # For example:
    # subparsers.add_parser('subcommand1')
    # subparsers.add_parser('subcommand2')

    try:
        arguments, _ = parser.parse_known_args(unparsed_arguments)
    except SystemExit:
        parser.print_help()
        sys.exit(0)

    if not arguments.subparser_name:
        namespace = parser.parse_args(unparsed_arguments)
        return {'global': namespace}

    subparser = sys.modules[__name__].__dict__[arguments.subparser_name]
    subparser.set_defaults(subparser_name=arguments.subparser_name)
    namespace = subparser.parse_args(unparsed_arguments)

    return {namespace.subparser_name: namespace}

