def deep_merge_nodes(nodes):
    result = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key not in result:
            result[key] = value_node
        else:
            if isinstance(result[key], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_value_node = deep_merge_mappings(result[key].value, value_node.value)
                result[key].value = merged_value_node
