def deep_merge_mappings(mappings1, mappings2):
    merged = {}

    for key, value in mappings1:
        merged[key.value] = value

    for key, value in mappings2:
        if key.value in merged:
            if isinstance(merged[key.value], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged[key.value] = deep_merge_mappings(merged[key.value].value, value.value)
            else:
                merged[key.value] = value
        else:
