def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("Invalid input: number should be an integer and alphabet should be a list of strings")

    if padding is not None and not isinstance(padding, int):
        raise ValueError("Invalid input: padding should be an integer or None")

    if number < 0:
        raise ValueError("Invalid input: number should be non-negative")

    if number == 0:
        return alphabet[0]

    num_str = ""
    while number > 0:
        num_str = alphabet[number % len(alphabet)] + num_str
        number //= len(alphabet)

    if padding is not None and len(num_str) < padding:
        num_str = num_str.zfill(padding)

    return num_str

