def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        raise ValueError("Input string cannot be empty")

    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    digit_map = {char: idx for idx, char in enumerate(alphabet)}

    value = 0
    for char in string:
        if char not in digit_map:
            raise ValueError(f"Character '{char}' not found in alphabet")
        value = value * len(alphabet) + digit_map[char]

    return value

def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        raise ValueError("Input string is empty")
    if not alphabet:
        raise ValueError("Alphabet is empty")
    if not all(char in alphabet for char in string):
        raise ValueError("String contains characters not in the alphabet")

    number = 0
    for char in string:
        number = number * len(alphabet) + alphabet.index(char)

    return number

