    try:
        value = os.getenv(env_name)
        if value is None:
            if default_value is None:
                raise KeyError(f"Environment variable '{env_name}' is not defined and no default value provided.")
            return default_value
        return value
    except Exception as e:
        raise RuntimeError(f"Error while resolving environment variable '{env_name}': {e}")

