from configparser import ConfigParser, ParsingError

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_results = {}
    log_records = []

    def resolve_variables(config):
        if resolve_env:
            for section in config.sections():
                for key in config[section]:
                    value = config[section][key]
                    config[section][key] = os.path.expandvars(value)

    for filename in config_filenames:
        try:
            config = ConfigParser()
            config.read(filename)
            resolve_variables(config)
            config_results[filename] = dict(config)  # Convert ConfigParser to dict for consistency
        except ParsingError as e:
            log_record = logging.LogRecord('ConfigParser', logging.ERROR, filename, None, f"Error parsing {filename}: {e}", None, None)
            log_records.append(log_record)

    if overrides:
        override_config = ConfigParser()
        override_config.read_dict(overrides)
        for section in override_config.sections():
            for key in override_config[section]:
                config_results[section][key] = override_config[section][key]

    return config_results, log_records

