def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if tentative:
        # Perform a more lenient verification
        requested_methods = set()
        requested_attributes = set()

        for method_name, method in iface.__dict__.items():
            if callable(method):
                requested_methods.add(method_name)
        for attribute_name in iface.__dict__:
            if not callable(getattr(iface, attribute_name)):
                requested_attributes.add(attribute_name)

        for method_name, method in candidate.__dict__.items():
            if callable(method) and method_name in requested_methods:
                requested_methods.remove(method_name)
        for attribute_name in candidate.__dict__:
            if not callable(getattr(candidate, attribute_name)) and attribute_name in requested_attributes:
                requested_attributes.remove(attribute_name)

        # If any methods or attributes still requested, candidate does not provide iface
        return not requested_methods and not requested_attributes
    else:
        # Perform a stricter verification
        for method_name, method in iface.__dict__.items():
            if callable(method):
                if not hasattr(candidate, method_name) or not callable(getattr(candidate, method_name)):
                    return False
        for attribute_name in iface.__dict__:
            if not callable(getattr(iface, attribute_name)):
                if not hasattr(candidate, attribute_name) or callable(getattr(candidate, attribute_name)):
                    return False
        return True
