def determineMetaclass(bases, explicit_mc=None) -> Type:
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check for explicit __metaclass__ in base classes
    for base in bases:
        if hasattr(base, '__metaclass__'):
            explicit_mc = base.__metaclass__
            break

    # If explicit metaclass is not provided, use the first base's metaclass
    if explicit_mc is None:
        for base in bases:
            if hasattr(base, '__metaclass__'):
                explicit_mc = base.__metaclass__
                break

    # If no metaclass is found, use type by default
    if explicit_mc is None:
        explicit_mc = type

    return explicit_mc
