class ISO8601Parser:
    @staticmethod
    def _parse_date_parts(date_str):
        date_parts = date_str.split('-')
        if len(date_parts) == 1:
            return int(date_parts[0]), None, None
        elif len(date_parts) == 2:
            return int(date_parts[0]), int(date_parts[1]), None
        elif len(date_parts) == 3:
            return int(date_parts[0]), int(date_parts[1]), int(date_parts[2])
        else:
            raise ValueError("Invalid date format")

    @staticmethod
    def _parse_time_parts(time_str):
        time_parts = time_str.split(':')
        if len(time_parts) == 1:
            return int(time_parts[0]), None, None, None, None
        elif len(time_parts) == 2:
            hh, mm = time_parts
            hh, mm = int(hh), int(mm)
            if hh == 24:
                hh = 0
            return hh, mm, 0, None, None
        elif len(time_parts) == 3:
            hh, mm, ss = time_parts
            hh, mm, ss = int(hh), int(mm), int(ss)
            if hh == 24:
                hh = 0
            return hh, mm, ss, 0, None
        elif len(time_parts) == 4:
            hh, mm, ss, ssssss = time_parts
            hh, mm, ss, ssssss = int(hh), int(mm), int(ss), int(ssssss)
            if hh == 24:
                hh = 0
            return hh, mm, ss, int(sssss * 1000000), None
        else:
            raise ValueError("Invalid time format")

    @staticmethod
    def _parse_tz_offset(tz_str):
        if tz_str == 'Z':
            return tzutc()
        elif tz_str.startswith('±'):
            sign = 1 if tz_str[1] == '+' else -1
           tz_str = tz_str[2:]
            if len(tz_str) == 2:
                hh, mm = tz_str
                hh, mm = int(hh), int(mm)
                return tzoffset(None, sign * (hh * 3600 + mm * 60))
            elif len(tz_str) == 4:
                hh, mm = tz_str[:2], tz_str[2:]
                hh, mm = int(hh), int(mm)
                return tzoffset(None, sign * (hh * 3600 + mm * 60))
            elif len(tz_str) == 1:
                hh = tz_str
                hh = int(hh)
                return tzoffset(None, sign * (hh * 3600))
            else:
                raise ValueError("Invalid time zone offset format")
        else:
            raise ValueError("Invalid time zone offset format")

    @_takes_ascii
    def isoparse(self, dt_str):
        date_match = re.match(r'^(\d{4})([-\w]+)?([-\w+]*?)$', dt_str)
        if not date_match:
            raise ValueError("Invalid ISO-8601 datetime string")
        date_str, time_str, tz_str = date_match.groups()

        year, month, day = self._parse_date_parts(date_str)
        hh, mm, ss, micro, week_num = (None, None, None, None, None)
        if time_str:
            hh, mm, ss, micro, week_num = self._parse_time_parts(time_str)
        if tz_str:
            tz_offset = self._parse_tz_offset(tz_str)
        else:
            tz_offset = tzutc()

        if week_num is not None:
            if day is not None:
                raise ValueError("ISO-8601 week and day cannot be combined with date")
            day = week_num % 7

        if month is None:
            return datetime(year, 1, 1, hh, mm, ss, micro, tz_offset)
        elif day is None and month is not None:
            return datetime(year, month, 1, hh, mm, ss, micro, tz_offset)
        elif day is not None and month is not None:
            return datetime(year, month, day, hh, mm, ss, micro, tz_offset)
        else:
            raise ValueError("Invalid ISO-8601 datetime string")
