def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    from typing import Set, Tuple

    tags = set()
    result = []
    in_code = False

    for line in text.split('\n'):
        parts = line.split('<')
        for part in parts:
            if part.startswith('/code>'):
                in_code = False
            elif part.startswith('code>'):
                in_code = True
            elif '<' in part and not in_code:
                parts = part.split('>')
                for tag in parts:
                    if tag.strip().startswith('/'):
                        if tag.strip() in tags:
                            tags.remove(tag.strip())
                    else:
                        tag = tag.strip()
                        if tag:
                            tags.add(tag)
                            if replacer:
                                result.append(replacer(tag))
                            else:
                                result.append(tag)
            else:
                if not in_code:
                    result.append(part)

    return tags, ''.join(result)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    buffer = []
    in_code_block = False
    in_tag = False
    for char in text:
        if char == '`':
            if in_code_block:
                in_code_block = False
            else:
                in_code_block = True
        if not in_code_block and char == '<' and not in_tag:
            in_tag = True
            buffer = []
        elif in_tag and char == '>':
            in_tag = False
            tag_word = ''.join(buffer)
            tags.add(tag_word)
        elif in_tag:
            buffer.append(char)
        if replacer and in_tag:
            char = replacer(tag_word)
        if in_tag:
            if char == '<':
                in_tag = False
        if not in_tag and not in_code_block:
            text = text[:index] + char + text[index+1:]
    return tags, text

