def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if "include" not in parser_dict:
        raise ValueError("No 'include' directive found in parser_dict.")

    include_path = parser_dict["include"]
    try:
        with open(include_path, 'r') as file:
            include_data = file.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Include file not found: {include_path}")
    except Exception as e:
        raise Exception(f"Error reading include file: {e}")

    try:
        include_dict = eval(include_data)
    except Exception as e:
        raise Exception(f"Error parsing include content as dict: {e}")

