    """Resolves the include dict directive in the spec files. """

    include_directives = parser_dict.get('_include', {})
    if not include_directives:
        return

    for include_path, include_data in include_directives.items():
        try:
            with open(include_path, 'r') as file:
                include_content = file.read()
                include_dict = eval(include_content)
                self._merge_dicts(parser_dict, include_dict)
        except (FileNotFoundError, IOError, SyntaxError) as e:
            raise ValueError(f"Failed to include file: {include_path}. Error: {e}")

def _merge_dicts(self, target, source):
    """Merges the source dictionary into the target dictionary recursively."""
    for key, value in source.items():
        if isinstance(value, dict):
            if key in target and isinstance(target[key], dict):
                self._merge_dicts(target[key], value)
            else:
                target[key] = value.copy()
        else:
            target[key] = value

