def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    # Step 1: Define a helper function to resolve default values
    def resolve_default(value):
        if callable(value):
            return value()
        else:
            return value

    # Step 2: Initialize a dictionary to store the resolved defaults
    resolved_defaults = {}

    # Step 3: Iterate over the spec and resolve default values
    for key, default in self.spec.get('defaults', {}).items():
        resolved_defaults[key] = resolve_default(default)

    # Step 4: Iterate over the required attributes and resolve default values
    for key, value in self.spec.get('attributes', {}).items():
        if 'default' in value:
            resolved_defaults[key] = resolve_default(value['default'])

    # Step 5: Return the resolved defaults
    return resolved_defaults
