            control_args[arg.lstrip('-- IRC behavior --')] = None
        elif arg.startswith('-- Nested args --'):
            nested_args[arg.lstrip('-- Nested args --')] = None
        elif arg.startswith('-- Custom vars --'):
            custom_args[arg.lstrip('-- Custom vars --')] = None
        else:
